static const uint32_t k_count = sizeof(k_table) / sizeof(k_table[0]);

static const AscOpcodeDesc* Find(uint32_t opcode)
{
    // table is generated in ascending opcode order
    uint32_t lo = 0, hi = k_count;
    while (lo < hi)
    {
        uint32_t mid = (lo + hi) / 2;
        if (k_table[mid].opcode < opcode) lo = mid + 1;
        else hi = mid;
    }
    return (lo < k_count && k_table[lo].opcode == opcode) ? &k_table[lo] : nullptr;
}

const char* NameOf(uint32_t opcode)        { const AscOpcodeDesc* d = Find(opcode); return d ? d->name : nullptr; }
const char* LayoutStateOf(uint32_t opcode) { const AscOpcodeDesc* d = Find(opcode); return d ? d->layoutState : nullptr; }
uint32_t Count()                           { return k_count; }

// One handler for every generated opcode: the dispatcher hands us the opcode, so the descriptor
// lookup does the rest. Signature matches CNetClientCustomPacket's handler.
static void __cdecl GenericHandler(void*, uint32_t opcode, uint32_t, CDataStore* ds)
{
    const AscOpcodeDesc* d = Find(opcode);
    if (!d) { CDataStore::IsRead(ds); return; }
    AscOpcodeParse(*d, ds);
}

void RegisterAll()
{
    for (uint32_t i = 0; i < k_count; ++i)
        sDC.AddPacketHandler(k_table[i].opcode, CNetClientCustomPacket((void*)&GenericHandler, nullptr));
    AscLog::Printf("AscOpcodes: registered %u generated extension handlers", k_count);
}

